// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // keep addresses non-zero to be widely admissible but avoid zero address trivially
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        // The admin is the deployer (this contract created C in setUp), which is address(this) as seen by C.
        // If caller is not the admin, then reference contract C should NOT allow caller to change owner.

        // ensure caller has ETH so a prank call can be made if needed
        vm.deal(caller, 1 ether);

        // record owner before the call
        address before = c.owner();

        // perform the call as `caller` to setOwner
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) returns (bool res) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, the reference contract guarantees: if caller != admin, owner must remain unchanged.
        // We can observe owner via the public getter. The single assertion encodes this universal rule.
        if (caller != address(this)) {
            // if caller is not admin, the call must either have failed or left owner unchanged
            assertTrue(c.owner() == before);
        } else {
            // if caller is admin, admin is allowed to change owner; so after admin call owner equals newOwner
            // but we still assert the general rule in the admin branch: owner equals newOwner when admin called
            assertTrue(c.owner() == newOwner);
        }
    }
}

