pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer; // admin in reference

    function setUp() public {
        deployer = address(this); // test contract deploys C via setUp
        c = new C();
    }

    // Fuzzed attacker address: if attacker == deployer (admin) then call should succeed in both versions;
    // if attacker != deployer but attacker == current owner (which initially equals deployer), we need to craft a scenario
    // where owner changes to a non-admin and then that owner tries to call setOwner. The mutant permits owner to call setOwner
    // while the reference does not. We fuzz the address of the non-admin newOwner.
    function testFuzz_property(address newOwner) public {
        // keep newOwner non-zero to be meaningful
        vm.assume(newOwner != address(0));
        // Ensure newOwner is different from deployer to create a non-admin owner scenario
        vm.assume(newOwner != deployer);

        // Step 1: as admin (deployer==this contract), set owner to newOwner. This should succeed in the reference contract.
        // We are already the deployer and admin, so call directly.
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        // In the reference implementation, admin (deployer) can call setOwner and it should succeed for any newOwner.
        // Assert that the call succeeded here to continue the test scenario.
        assertTrue(ok);

        // At this point, c.owner() == newOwner
        address ownerAfter = c.owner();
        assertTrue(ownerAfter == newOwner);

        // Now, the crucial check: a call to setOwner by the current owner (newOwner) should be rejected by the reference
        // (onlyAdmin requires msg.sender == admin). The mutant accepts owner as admin and would allow this.
        // We simulate a call from newOwner using vm.prank. The fuzzer provided newOwner, so this is adversarial input.
        address attacker = newOwner;
        address proposed = address(0x123); // this is not fuzzed; it's only a target to attempt to set

        // Ensure the attacker has some ETH for call cost (not strictly necessary but safe)
        vm.deal(attacker, 1 ether);
        vm.prank(attacker);
        try c.setOwner(proposed) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: in the correct contract, a call to setOwner by the current owner (who is not the original admin)
        // must fail (only admin can call). Thus ok must be false for all admissible newOwner != deployer.
        // The mutant that checks owner instead of admin will make ok true for some inputs (when attacker==owner), so this assert
        // will fail on the mutant for those inputs.
        assertTrue(!ok);
    }
}

