pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address admin;

    function setUp() public { c = new C(); admin = address(this); }

    // fuzzed parameter: the candidate new owner address
    function testFuzz_property(address newOwner) public {
        // keep domain wide but avoid zero-address is allowed by contract so no restriction necessary
        // act as admin (the deployer / this contract is admin)
        // Call setOwner and capture whether it returns true when it doesn't revert
        bool ok;
        bool ret;
        try c.setOwner(newOwner) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false;
        }

        // General rule: when call does not revert (ok == true), reference always returns true.
        // The single assertion: either the call reverted (ok == false) OR it returned true (ret == true).
        // This will pass on the reference for all inputs, and fail on the mutant for some input where it returns false without reverting.
        assertTrue(!ok || ret);
    }
}

