import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz the address to be set as owner. The rule: for any fuzzed owner address,
    // calling setOwner as admin completes and returns true in the reference.
    // The mutant may return false for some _owner values (when it compares to previous owner),
    // so this test will fail on the mutant for some fuzzed inputs.
    function testFuzz_property(address newOwner) public {
        // widen domain: allow any address (including zero);
        // ensure the caller is the admin (deployer from setUp). Use vm.prank to call as admin.
        bool ok;
        vm.prank(address(this)); // set msg.sender to this test contract by default (not admin)
        // The contract's admin is the deployer of C which is this test's address (setUp called new C() from this contract),
        // so we must call setOwner as that admin. Use vm.prank(address(this)). However, vm.prank affects the next call only,
        // so we directly make the call under that prank.
        vm.prank(address(this));
        try c.setOwner(newOwner) returns (bool ret) {
            ok = ret;
        } catch {
            // should not revert under reference for any newOwner since onlyAdmin (we call as admin)
            ok = false;
        }

        // The reference implementation always returns true after successful call; assert that return is true.
        // This single assertion is satisfied by the correct contract for all inputs, but the mutant returns false for some inputs.
        assertTrue(ok);
    }
}

