        try c.setOwner(newOwner) returns (bool r) { ok = true; ret = r; } catch { ok = false; ret = false; }

        // General rule: in the reference contract, any successful setOwner call returns true.
        // So for all inputs where the call does not revert (ok == true), the return value must be true.
        // The mutant can produce ok == true but ret == false for some newOwner values.
        assertTrue(!ok || ret);
