pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed param: an arbitrary caller address which may or may not be the admin
    function testFuzz_property(address caller) public {
        // keep wide domain but exclude zero address to avoid degenerate scenarios
        vm.assume(caller != address(0));

        // Try calling setOwner with the fuzzed caller as msg.sender, targetting the caller as new owner.
        // In the reference contract, only the admin (the deployer, which is this test contract) can call
        // setOwner successfully. For any other caller, the call should revert. We observe success via try/catch.

        bool ok;
        // run the call as the fuzzed caller
        vm.prank(caller);
        try c.setOwner(caller) returns (bool res) {
            ok = res;
        } catch {
            ok = false;
        }

        // The general rule: only the admin (this test contract) can successfully call setOwner.
        // Therefore for EVERY caller != address(this) the call must NOT succeed (ok == false),
        // and for caller == address(this) it must succeed (ok == true).
        // This single assert combines both by checking equivalence between success and being the admin.
        assertTrue(ok == (caller == address(this)));
    }
}

