pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameter: candidate new owner address
    function testFuzz_property(address newOwner) public {
        // keep address admissible (not zero to make meaningful ownership change), but allow wide space
        vm.assume(newOwner != address(0));

        // call setOwner as admin (setUp deployer is admin/owner). msg.sender of setUp is this test contract,
        // so we must prank as the deployer. In Foundry tests, the default msg.sender for setUp/new is address(this),
        // so we call as that address.
        address caller = address(this);
        vm.prank(caller);

        // perform the call and capture whether it reverted and its returned boolean via low-level call
        // since Solidity doesn't let us directly capture return of external non-view when using the imported ABI,
        // we use try/catch to get revert behavior and then call via low-level to decode the returned bool.

        // First call via high-level to observe behavior and update owner if reference contract.
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // We require the call succeeded (both reference and mutant return true without reverting), so assert only when call succeeded.
        vm.assume(ok == true);

        // Now read the public owner getter to observe whether owner was updated.
        address observedOwner = c.owner();

        // General rule (single assertion): After a successful setOwner call by admin, the contract's owner must equal the provided newOwner.
        // The reference satisfies this for all inputs; the mutant that returns early before assignment will fail for some inputs.
        assertTrue(observedOwner == newOwner);
    }
}
